answer.python_code:
zs = sorted(set(r['z'] for r in rows))
total = sum(r['weight'] for r in rows)
pz = {z: Fraction(sum(r['weight'] for r in rows if r['z'] == z), total) for z in zs}
risk = {(x, z): Fraction(sum(r['weight'] * r['y'] for r in rows if r['x'] == x and r['z'] == z), sum(r['weight'] for r in rows if r['x'] == x and r['z'] == z)) for x in (0, 1) for z in zs}
estimate = sum(pz[z] * (risk[1, z] - risk[0, z]) for z in zs)
